import torch


def _key_sequence(start, count, device):
    # An affine permutation modulo 2**31 gives distinct, non-sentinel int32 keys.
    indices = torch.arange(start, start + count, dtype=torch.int64, device=device)
    return ((indices * 1_103_515_245 + 12_345) & 0x7FFF_FFFF).to(torch.int32)


def _sample_indices(num_keys, count, zipf_alpha_milli, device):
    if count == 0:
        return torch.empty(0, dtype=torch.int64, device=device)
    if zipf_alpha_milli == 0:
        return torch.randint(0, num_keys, (count,), device=device)
    alpha = zipf_alpha_milli / 1000.0
    ranks = torch.arange(1, num_keys + 1, dtype=torch.float32, device=device)
    weights = ranks.pow(-alpha)
    return torch.multinomial(weights, count, replacement=True)


def generate_inputs(axes_and_scalars, device):
    build_size = axes_and_scalars['build_size']
    unique_keys = axes_and_scalars['unique_keys']
    probe_size = axes_and_scalars['probe_size']
    hit_rate_percent = axes_and_scalars['hit_rate_percent']
    zipf_alpha_milli = axes_and_scalars['zipf_alpha_milli']

    if not 0 < unique_keys <= build_size:
        raise ValueError('unique_keys must be in [1, build_size]')
    if not 0 <= hit_rate_percent <= 100:
        raise ValueError('hit_rate_percent must be in [0, 100]')
    if zipf_alpha_milli < 0:
        raise ValueError('zipf_alpha_milli must be non-negative')

    key_universe = _key_sequence(0, unique_keys, device)
    extra_count = build_size - unique_keys
    if zipf_alpha_milli == 0:
        extra_indices = torch.arange(extra_count, dtype=torch.int64, device=device) % unique_keys
    else:
        extra_indices = _sample_indices(
            unique_keys, extra_count, zipf_alpha_milli, device
        )
    build_keys = torch.cat((key_universe, key_universe[extra_indices]))
    build_keys = build_keys[torch.randperm(build_size, device=device)]

    num_hits = probe_size * hit_rate_percent // 100
    hit_indices = _sample_indices(
        unique_keys, num_hits, zipf_alpha_milli, device
    )
    hits = key_universe[hit_indices]
    misses = _key_sequence(unique_keys, probe_size - num_hits, device)
    probe_keys = torch.cat((hits, misses))
    probe_keys = probe_keys[torch.randperm(probe_size, device=device)]
    return {'build_keys': build_keys, 'probe_keys': probe_keys}


@torch.no_grad()
def run(build_keys, probe_keys):
    sorted_build = torch.sort(build_keys).values
    lower = torch.searchsorted(sorted_build, probe_keys, right=False)
    upper = torch.searchsorted(sorted_build, probe_keys, right=True)
    return upper - lower
